65	async fn run_remote_compact_task_inner_impl(
66	    sess: &Arc<Session>,
67	    turn_context: &Arc<TurnContext>,
68	    initial_context_injection: InitialContextInjection,
69	) -> CodexResult<()> {
70	    let compaction_item = TurnItem::ContextCompaction(ContextCompactionItem::new());
71	    sess.emit_turn_item_started(turn_context, &compaction_item)
72	        .await;
73	    let mut history = sess.clone_history().await;
74	    let base_instructions = sess.get_base_instructions().await;
75	    let deleted_items = trim_function_call_history_to_fit_context_window(
76	        &mut history,
77	        turn_context.as_ref(),
78	        &base_instructions,
79	    );
80	    if deleted_items > 0 {
81	        info!(
82	            turn_id = %turn_context.sub_id,
83	            deleted_items,
84	            "trimmed history items before remote compaction"
85	        );
86	    }
87	    // Required to keep `/undo` available after compaction
88	    let ghost_snapshots: Vec<ResponseItem> = history
89	        .raw_items()
90	        .iter()
91	        .filter(|item| matches!(item, ResponseItem::GhostSnapshot { .. }))
92	        .cloned()
93	        .collect();
94	
95	    let prompt = Prompt {
96	        input: history.for_prompt(&turn_context.model_info.input_modalities),
97	        tools: vec![],
98	        parallel_tool_calls: false,
99	        base_instructions,
100	        personality: turn_context.personality,
101	        output_schema: None,
102	    };
103	
104	    let mut new_history = sess
105	        .services
106	        .model_client
107	        .compact_conversation_history(
108	            &prompt,
109	            &turn_context.model_info,
110	            &turn_context.session_telemetry,
111	        )
112	        .or_else(|err| async {
113	            let total_usage_breakdown = sess.get_total_token_usage_breakdown().await;
114	            let compact_request_log_data =
115	                build_compact_request_log_data(&prompt.input, &prompt.base_instructions.text);
116	            log_remote_compact_failure(
117	                turn_context,
118	                &compact_request_log_data,
119	                total_usage_breakdown,
120	                &err,
121	            );
122	            Err(err)
123	        })
124	        .await?;
125	    new_history = process_compacted_history(
126	        sess.as_ref(),
127	        turn_context.as_ref(),
128	        new_history,
129	        initial_context_injection,
130	    )
131	    .await;
132	
133	    if !ghost_snapshots.is_empty() {
134	        new_history.extend(ghost_snapshots);
135	    }
136	    let reference_context_item = match initial_context_injection {
137	        InitialContextInjection::DoNotInject => None,
138	        InitialContextInjection::BeforeLastUserMessage => Some(turn_context.to_turn_context_item()),
139	    };
140	    let compacted_item = CompactedItem {
141	        message: String::new(),
142	        replacement_history: Some(new_history.clone()),
143	    };
144	    sess.replace_compacted_history(new_history, reference_context_item, compacted_item)
145	        .await;
146	    sess.recompute_token_usage(turn_context).await;
147	
148	    sess.emit_turn_item_completed(turn_context, compaction_item)
149	        .await;
150	    Ok(())
151	}
