175	/// Returns whether an item from remote compaction output should be preserved.
176	///
177	/// Called while processing the model-provided compacted transcript, before we
178	/// append fresh canonical context from the current session.
179	///
180	/// We drop:
181	/// - `developer` messages because remote output can include stale/duplicated
182	///   instruction content.
183	/// - non-user-content `user` messages (session prefix/instruction wrappers),
184	///   keeping only real user messages as parsed by `parse_turn_item`.
185	///
186	/// This intentionally keeps:
187	/// - `assistant` messages (future remote compaction models may emit them)
188	/// - `user`-role warnings and compaction-generated summary messages because
189	///   they parse as `TurnItem::UserMessage`.
190	fn should_keep_compacted_history_item(item: &ResponseItem) -> bool {
191	    match item {
192	        ResponseItem::Message { role, .. } if role == "developer" => false,
193	        ResponseItem::Message { role, .. } if role == "user" => {
194	            matches!(
195	                crate::event_mapping::parse_turn_item(item),
196	                Some(TurnItem::UserMessage(_))
197	            )
198	        }
199	        ResponseItem::Message { role, .. } if role == "assistant" => true,
