282	        prompt: &Prompt,
283	        model_info: &ModelInfo,
284	        session_telemetry: &SessionTelemetry,
285	    ) -> Result<Vec<ResponseItem>> {
286	        if prompt.input.is_empty() {
287	            return Ok(Vec::new());
288	        }
